CREATE FUNCTION dg_native_bill_quote_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE q restaurant_financial_quotes%ROWTYPE;fixed _dg_native_bill_quote_origins%ROWTYPE;payload jsonb;reason_value text;
BEGIN
 SELECT * INTO q FROM restaurant_financial_quotes WHERE id=target;SELECT * INTO fixed FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;payload:=q.payload::jsonb;reason_value:=dg_native_bill_quote_reason(q.id,meta);
 RETURN jsonb_build_object('id',q.id,'billId',q.bill_id,'kind',q.kind,'parentPaymentId',q.parent_payment_id,'hash',q.hash,'billVersion',(payload->>'billVersion')::bigint,'orderContentVersion',(payload->>'orderContentVersion')::bigint,'amountMinor',(payload->>'amountMinor')::bigint,'currency','CNY','reason',payload->>'reason','lines',payload->'lines','valid',reason_value IS NULL,'invalidReason',reason_value,'confirmationToken',NULL,'expiresAt',q.expires_at,'createdAt',q.created_at,'_confirmation',CASE WHEN reason_value IS NULL THEN jsonb_build_object('quoteId',q.id,'meta',fixed.actor_meta,'hash',fixed.confirmation_hash) END);
END;$dg$;

CREATE FUNCTION dg_native_bill_operation_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;manager_value boolean;can_withdraw boolean;
BEGIN
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;manager_value:=dg_native_bill_manager(meta);can_withdraw:=operation.status='queued' AND operation.send_attempts=0 AND operation.lease_token IS NULL AND(operation.kind='payment' OR manager_value) AND(meta->>'actorType'='staff' OR dg_native_order_source(meta,meta->>'partyId'));
 RETURN jsonb_build_object('id',operation.id,'billId',operation.bill_id,'kind',operation.kind,'parentPaymentId',operation.parent_payment_id,'status',operation.status,'version',operation.version,'amountMinor',operation.amount_minor,'currency','CNY','reason',CASE WHEN operation.kind='refund' AND NOT manager_value THEN '门店经理核对退款' ELSE operation.reason END,'simulated',operation.simulated=1,'sendAttempts',operation.send_attempts,'simulateAttempts',operation.simulate_attempts,'lookups',operation.lookups,'nextAction',operation.next_action,'checkoutReady',false,'canSimulate',false,'canQuery',false,'canClose',false,'canWithdraw',can_withdraw,'refundableMinor',CASE WHEN operation.kind='payment' THEN coalesce(dg_native_bill_refundable(operation.id),0) ELSE 0 END,'remoteOperationId',operation.remote_operation_id,'remoteTransactionId',operation.remote_transaction_id,'errorMessage',operation.error_message,'createdAt',operation.created_at,'updatedAt',operation.updated_at);
END;$dg$;

CREATE FUNCTION dg_native_bill_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;t jsonb;reason_value text;connection jsonb;manager_value boolean;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;t:=dg_native_bill_totals(b.id);reason_value:=dg_native_bill_payment_reason(o.id,meta);connection:=dg_native_bill_connection(b.restaurant_id);manager_value:=dg_native_bill_manager(meta);
 IF reason_value IS NULL THEN
  IF(t->>'activePayments')::bigint>0 OR(t->>'activeRefunds')::bigint>0 THEN reason_value:='请先核对原资金请求，不能重复付款。';ELSIF(t->>'paid')::bigint>0 OR(t->>'balance')::bigint<=0 THEN reason_value:='此账单已无新的待收金额，请查看原收款及退款事实。';ELSIF b.attention_reason IS NOT NULL THEN reason_value:=b.attention_reason;ELSIF NOT(connection->>'configured')::boolean THEN reason_value:=connection->>'notice';END IF;
 END IF;
 RETURN jsonb_build_object('id',b.id,'restaurantId',b.restaurant_id,'partyId',b.party_id,'orderId',b.order_id,'orderVersion',o.version,'orderNumber',o.number,'number',b.number,'version',b.version,'orderContentVersion',b.order_content_version,'status',b.status,'totalMinor',b.amount_minor,'paidMinor',(t->>'paid')::bigint,'refundedMinor',(t->>'refunded')::bigint,'reservedRefundMinor',(t->>'reserved')::bigint,'balanceMinor',(t->>'balance')::bigint,'currency','CNY','attentionReason',b.attention_reason,'staleReason',CASE WHEN o.content_version<>b.order_content_version THEN '实际接单明细已变化，旧账单不能继续付款，请重新审阅。' END,'canReview',reason_value IS NULL,'reviewReason',reason_value,'canRefund',manager_value AND EXISTS(SELECT 1 FROM restaurant_financial_operations operation WHERE operation.bill_id=b.id AND operation.kind='payment' AND dg_native_bill_refundable(operation.id)>0),'settledAt',b.settled_at,'lines',b.snapshot::jsonb,
  'operations',(SELECT coalesce(jsonb_agg(dg_native_bill_operation_project(operation.id,meta) ORDER BY operation.created_at DESC,operation.id DESC),'[]') FROM restaurant_financial_operations operation JOIN _dg_native_bill_operation_origins fixed ON fixed.operation_id=operation.id WHERE operation.bill_id=b.id),
  'quotes',(SELECT coalesce(jsonb_agg(dg_native_bill_quote_project(quote.id,meta) ORDER BY quote.created_at DESC,quote.id DESC),'[]') FROM(SELECT q.id,q.created_at FROM restaurant_financial_quotes q JOIN _dg_native_bill_quote_origins fixed ON fixed.quote_id=q.id WHERE q.bill_id=b.id AND q.actor_id=meta->>'actorId' AND(q.kind='payment' OR manager_value) ORDER BY q.created_at DESC,q.id DESC LIMIT 10) quote),
  'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',event.id,'kind',event.kind,'message',event.info::jsonb->>'message','createdAt',event.created_at) ORDER BY event.created_at DESC,event.id DESC),'[]') FROM(SELECT * FROM restaurant_financial_events WHERE bill_id=b.id ORDER BY created_at DESC,id DESC LIMIT 50) event),'createdAt',b.created_at,'updatedAt',b.updated_at);
END;$dg$;

CREATE FUNCTION dg_native_bill_read(kind_value text,target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;connection jsonb;
BEGIN
 IF kind_value NOT IN('restaurant','party','bill') THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;meta:=dg_native_bill_context(kind_value,target,session_value,token_value);connection:=dg_native_bill_connection(meta->>'restaurantId',dg_native_bill_manager(meta));
 IF kind_value='restaurant' THEN RETURN connection;ELSIF kind_value='bill' THEN RETURN dg_native_bill_project(target,meta);END IF;
 RETURN jsonb_build_object('partyId',target,'bills',(SELECT coalesce(jsonb_agg(dg_native_bill_project(bill.id,meta) ORDER BY bill.created_at DESC,bill.id DESC),'[]') FROM(SELECT b.id,b.created_at FROM restaurant_bills b JOIN _dg_native_bill_origins fixed ON fixed.bill_id=b.id WHERE b.party_id=target ORDER BY b.created_at DESC,b.id DESC LIMIT 50) bill),'unbilledOrders',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',current_order.id,'number',current_order.number,'version',current_order.version,'contentVersion',current_order.content_version,'status',current_order.status,'totalMinor',coalesce((SELECT sum((line.quantity-line.cancelled_quantity)*line.unit_price_minor) FROM restaurant_order_lines line WHERE line.order_id=current_order.id),0)) ORDER BY current_order.created_at DESC,current_order.id DESC),'[]') FROM restaurant_orders current_order JOIN _dg_native_order_origins fixed ON fixed.order_id=current_order.id WHERE current_order.party_id=target AND NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=current_order.id) AND EXISTS(SELECT 1 FROM restaurant_order_lines line WHERE line.order_id=current_order.id AND line.quantity>line.cancelled_quantity)),'connection',connection-ARRAY['canManage','scenario'],'automatic',meta->>'actorType'='staff' OR dg_native_order_source(meta,target),'canManage',dg_native_bill_manager(meta));
END;$dg$;

CREATE FUNCTION dg_native_bill_result(target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE result_value _dg_native_bill_results%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;meta jsonb;
BEGIN
 SELECT * INTO result_value FROM _dg_native_bill_results WHERE action_id=target;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=target;IF result_value.action_id IS NULL THEN PERFORM dg_native_bill_error('NOT_FOUND');END IF;
 meta:=dg_native_bill_context(CASE WHEN actual_action.resource_type='restaurant' THEN 'restaurant' ELSE 'party' END,actual_action.resource_id,session_value,token_value);
 IF actual_action.actor_type IS DISTINCT FROM meta->>'actorType' OR actual_action.actor_id IS DISTINCT FROM meta->>'actorId' OR actual_action.actor_epoch IS DISTINCT FROM(meta->>'actorEpoch')::bigint OR actual_action.grant_version IS DISTINCT FROM(meta->>'grantVersion')::bigint OR actual_action.session_id IS DISTINCT FROM meta->>'sessionId' OR actual_action.access_id IS DISTINCT FROM meta->>'accessId' OR actual_action.focus_version IS DISTINCT FROM(meta->>'focusVersion')::bigint OR actual_action.selection_version IS DISTINCT FROM(meta->>'selectionVersion')::bigint OR result_value.party_access_version IS DISTINCT FROM(meta->>'partyAccessVersion')::bigint THEN PERFORM dg_native_bill_error('AUTHORIZATION_CHANGED');END IF;
 IF actual_action.kind='bill_config' THEN IF NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;RETURN dg_native_bill_connection(result_value.restaurant_id,true);END IF;RETURN dg_native_bill_project(result_value.bill_id,meta);
END;$dg$;
